const dropAddZero: ts.TransformerFactory<ts.SourceFile> = (context) => (file) => {
  const visit: ts.Visitor = (node) => {
    if (ts.isBinaryExpression(node) &&
        node.operatorToken.kind === ts.SyntaxKind.PlusToken &&
        ts.isNumericLiteral(node.right) && node.right.text === "0") {
      return node.left;                                // x + 0 -> x
    }
    return ts.visitEachChild(node, visit, context);     // library owns the walk
  };
  return ts.visitNode(file, visit) as ts.SourceFile;
};
